(* [comment removed for export] *)
Definition FRM9 (m : word -> option byte) (s : Z) (ret : word) (regs : bvmap 5 word) : word -> option byte :=
  wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes (wbytes m
    (Z_to_bv 64 (s - 8)) (word_to_le_bytes 8 ret))
    (Z_to_bv 64 (s - 16)) (word_to_le_bytes 8 (getr regs 8)))
    (Z_to_bv 64 (s - 24)) (word_to_le_bytes 8 (getr regs 9)))
    (Z_to_bv 64 (s - 32)) (word_to_le_bytes 8 (getr regs 18)))
    (Z_to_bv 64 (s - 40)) (word_to_le_bytes 8 (getr regs 19)))
    (Z_to_bv 64 (s - 48)) (word_to_le_bytes 8 (getr regs 20)))
    (Z_to_bv 64 (s - 56)) (word_to_le_bytes 8 (getr regs 21)))
    (Z_to_bv 64 (s - 64)) (word_to_le_bytes 8 (getr regs 22)))
    (Z_to_bv 64 (s - 72)) (word_to_le_bytes 8 (getr regs 23)).
(* [comment removed for export] *)
Definition DIM2 (m : word -> option byte) (s w h : Z) : word -> option byte :=
  wbytes (wbytes (wbytes (wbytes m
    (Z_to_bv 64 (s - 76)) (word_to_le_bytes 4 (Z_to_bv 64 0)))
    (Z_to_bv 64 (s - 80)) (word_to_le_bytes 4 (Z_to_bv 64 0)))
    (Z_to_bv 64 (s - 76)) (word_to_le_bytes 4 (Z_to_bv 64 w)))
    (Z_to_bv 64 (s - 80)) (word_to_le_bytes 4 (Z_to_bv 64 h)).

Section Segs.
Variable rom : word -> option byte.

  (* [comment removed for export] *)
  Lemma am_A : forall regs m (s pixs l r t b : Z) (vs : pixv) (ret : word),
    (96 <= s)%Z -> (s < 2 ^ 64)%Z -> (1 <= pixs)%Z -> PIXat m pixs vs -> (pixs + 64 <= s - 96 \/ s <= pixs)%Z ->
    (0 <= l < 2 ^ 31)%Z -> (0 <= r < 2 ^ 31)%Z -> (0 <= t < 2 ^ 31)%Z -> (0 <= b < 2 ^ 31)%Z ->
    (l <= p_w vs)%Z -> (r <= p_w vs)%Z -> (t <= p_h vs)%Z -> (b <= p_h vs)%Z ->
    store_ok SEGS m (Z_to_bv 64 (s - 96)) 96 = true ->
    getr regs 2 = Z_to_bv 64 s -> getr regs 1 = ret -> getr regs 10 = Z_to_bv 64 pixs ->
    getr regs 11 = Z_to_bv 64 l -> getr regs 12 = Z_to_bv 64 r -> getr regs 13 = Z_to_bv 64 t -> getr regs 14 = Z_to_bv 64 b ->
    exists regs',
      msteps SEGS (mkst regs (0x1b714 : word) m rom)
                  (mkst regs' (0x1b458 : word) (DIM2 (FRM9 m s ret regs) s (p_w vs) (p_h vs)) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 96) /\ getr regs' 1 = Z_to_bv 64 0x1b798
      /\ getr regs' 10 = Z_to_bv 64 pixs /\ getr regs' 11 = Z_to_bv 64 l /\ getr regs' 12 = Z_to_bv 64 r
      /\ getr regs' 13 = Z_to_bv 64 t /\ getr regs' 14 = Z_to_bv 64 b /\ getr regs' 15 = Z_to_bv 64 0
      /\ getr regs' 9 = Z_to_bv 64 pixs /\ getr regs' 19 = Z_to_bv 64 l /\ getr regs' 20 = Z_to_bv 64 r
      /\ getr regs' 8 = Z_to_bv 64 t /\ getr regs' 18 = Z_to_bv 64 b
      /\ regs_agree (fun x => In x [1; 2; 8; 9; 10; 11; 12; 13; 14; 15; 18; 19; 20]%list) regs regs'.
Proof.
