  (* [comment removed for export] *)
  Lemma am_B1 : forall regs m (l r : Z),
    (0 <= l < 2 ^ 30)%Z -> (1 <= r < 2 ^ 30)%Z -> getr regs 19 = Z_to_bv 64 l -> getr regs 20 = Z_to_bv 64 r ->
    exists regs',
      msteps SEGS (mkst regs (0x1b7e0 : word) m rom) (mkst regs' (0x1b7ec : word) m rom)
      /\ getr regs' 21 = Z_to_bv 64 (r + l) /\ getr regs' 20 = Z_to_bv 64 (l - 1)
      /\ regs_agree (fun x => In x [20; 21]%list) regs regs'.
Proof.
