  (* [comment removed for export] *)
  Lemma am_L2 : forall regs m (s pixd t w h p q : Z),
    (96 <= s)%Z -> (s < 2 ^ 64)%Z -> (0 <= w < 2 ^ 30)%Z -> (0 <= h < 2 ^ 31)%Z -> (0 <= p < 2 ^ 30)%Z -> (- 2 ^ 30 < q < 2 ^ 30)%Z ->
    rdn SEGS m (Z_to_bv 64 (s - 76)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 w)) ->
    rdn SEGS m (Z_to_bv 64 (s - 80)) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 h)) ->
    store_ok SEGS m (Z_to_bv 64 (s - 96)) 8 = true ->
    getr regs 2 = Z_to_bv 64 (s - 96) -> getr regs 9 = Z_to_bv 64 pixd -> getr regs 8 = Z_to_bv 64 t ->
    getr regs 19 = Z_to_bv 64 p -> getr regs 20 = Z_to_bv 64 q ->
    exists regs',
      msteps SEGS (mkst regs (0x1b7ec : word) m rom)
                  (mkst regs' (0x23444 : word) (wbytes m (Z_to_bv 64 (s - 96)) (word_to_le_bytes 8 (Z_to_bv 64 t))) rom)
      /\ getr regs' 2 = Z_to_bv 64 (s - 96) /\ getr regs' 1 = Z_to_bv 64 0x1b818
      /\ getr regs' 10 = Z_to_bv 64 pixd /\ getr regs' 11 = Z_to_bv 64 (p + w) /\ getr regs' 12 = Z_to_bv 64 t /\ getr regs' 13 = Z_to_bv 64 1
      /\ getr regs' 14 = Z_to_bv 64 h /\ getr regs' 15 = Z_to_bv 64 12 /\ getr regs' 16 = Z_to_bv 64 pixd /\ getr regs' 17 = Z_to_bv 64 (q + w)
      /\ regs_agree (fun x => In x [1; 10; 11; 12; 13; 14; 15; 16; 17]%list) regs regs'.
Proof.
