  (* [comment removed for export] *)
  Lemma am_N2 : forall (last : bool) regs m (p q e : Z),
    (0 <= p < 2 ^ 30)%Z -> (- 2 ^ 30 < q < 2 ^ 30)%Z -> (p + 1 <= e < 2 ^ 30)%Z -> (if last then p + 1 = e else p + 1 < e)%Z ->
    getr regs 19 = Z_to_bv 64 p -> getr regs 20 = Z_to_bv 64 q -> getr regs 21 = Z_to_bv 64 e ->
    exists regs',
      msteps SEGS (mkst regs (0x1b818 : word) m rom) (mkst regs' (if last then (0x1b824 : word) else (0x1b7ec : word)) m rom)
      /\ getr regs' 19 = Z_to_bv 64 (p + 1) /\ getr regs' 20 = Z_to_bv 64 (q - 1)
      /\ regs_agree (fun x => In x [19; 20]%list) regs regs'.
Proof.
