  (* [comment removed for export] *)
  Lemma am_B2 : forall regs m (t : Z),
    (1 <= t < 2 ^ 31)%Z -> getr regs 8 = Z_to_bv 64 t ->
    exists regs',
      msteps SEGS (mkst regs (0x1b824 : word) m rom) (mkst regs' (0x1b834 : word) m rom)
      /\ getr regs' 19 = Z_to_bv 64 (t - 1) /\ getr regs' 20 = Z_to_bv 64 (-1) /\ getr regs' 22 = Z_to_bv 64 t
      /\ regs_agree (fun x => In x [19; 20; 22]%list) regs regs'.
