  (* [comment removed for export] *)
  Lemma am_N3 : forall (last : bool) regs m (a c : Z),
    (0 <= a < 2 ^ 31)%Z -> (0 <= c < 2 ^ 31 - 1)%Z -> (if last then a = 0 else 0 < a)%Z ->
    getr regs 19 = Z_to_bv 64 a -> getr regs 22 = Z_to_bv 64 c -> getr regs 20 = Z_to_bv 64 (-1) ->
    exists regs',
      msteps SEGS (mkst regs (0x1b860 : word) m rom) (mkst regs' (if last then (0x1b86c : word) else (0x1b834 : word)) m rom)
      /\ getr regs' 19 = Z_to_bv 64 (a - 1) /\ getr regs' 22 = Z_to_bv 64 (c + 1)
      /\ regs_agree (fun x => In x [19; 22]%list) regs regs'.
Proof.
