  (* [comment removed for export] *)
  Lemma am_B3 : forall regs m (t b : Z),
    (0 <= t < 2 ^ 30)%Z -> (1 <= b < 2 ^ 30)%Z -> getr regs 8 = Z_to_bv 64 t -> getr regs 18 = Z_to_bv 64 b ->
    exists regs',
      msteps SEGS (mkst regs (0x1b86c : word) m rom) (mkst regs' (0x1b878 : word) m rom)
      /\ getr regs' 19 = Z_to_bv 64 (t - 1) /\ getr regs' 18 = Z_to_bv 64 (b + t)
      /\ regs_agree (fun x => In x [18; 19]%list) regs regs'.
Proof.
