  (* [comment removed for export] *)
  Lemma am_N4 : forall (last : bool) regs m (p q e : Z),
    (0 <= p < 2 ^ 30)%Z -> (- 2 ^ 30 < q < 2 ^ 30)%Z -> (p + 1 <= e < 2 ^ 30)%Z -> (if last then p + 1 = e else p + 1 < e)%Z ->
    getr regs 8 = Z_to_bv 64 p -> getr regs 19 = Z_to_bv 64 q -> getr regs 18 = Z_to_bv 64 e ->
    exists regs',
      msteps SEGS (mkst regs (0x1b8ac : word) m rom) (mkst regs' (if last then (0x1b948 : word) else (0x1b878 : word)) m rom)
      /\ getr regs' 8 = Z_to_bv 64 (p + 1) /\ getr regs' 19 = Z_to_bv 64 (q - 1)
      /\ regs_agree (fun x => In x [8; 19]%list) regs regs'.
